package com.voicex.pro;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.PixelFormat;import android.view.*;import android.widget.*;
public class EdgeService extends Service {
 WindowManager wm; View view;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("edge","Gaming overlay",NotificationManager.IMPORTANCE_LOW));startForeground(7,new Notification.Builder(this,"edge").setSmallIcon(android.R.drawable.ic_btn_speak_now).setContentTitle("VOICE X PRO").setContentText("Overlay active; game mic unchanged").setOngoing(true).build());wm=getSystemService(WindowManager.class);show(false,false);}
 void add(LinearLayout l,String title,Runnable r){Button b=new Button(this);b.setText(title);b.setTextSize(11);b.setTextColor(-1);b.setBackground(MainActivity.bg(0xff513589));l.addView(b,new LinearLayout.LayoutParams(-1,dp(40)));b.setOnClickListener(v->r.run());}
 void show(boolean expanded,boolean settings){if(view!=null){try{wm.removeView(view);}catch(IllegalArgumentException ignored){}view=null;}LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setBackground(MainActivity.bg(expanded?0xee171124:0xff9765ef));if(expanded){add(l,settings?"HOME":"SETTINGS",()->show(true,!settings));TextView t=new TextView(this);t.setTextColor(-1);t.setText(settings?"Recording pitch":"Game mic unchanged");l.addView(t);if(settings){SeekBar s=new SeekBar(this);s.setMax(60);s.setProgress(getSharedPreferences("voice",0).getInt("pitch",25));l.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int x,boolean u){getSharedPreferences("voice",0).edit().putInt("pitch",x).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});}add(l,"Hide",()->show(false,false));add(l,"Close",this::stopSelf);}else{l.setContentDescription("Open VOICE X PRO panel");l.setOnClickListener(v->show(true,false));l.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_UP)v.performClick();return true;});}
 WindowManager.LayoutParams p=new WindowManager.LayoutParams(dp(expanded?170:8),expanded?-2:dp(78),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.RIGHT|Gravity.CENTER_VERTICAL;try{wm.addView(l,p);view=l;}catch(Exception e){stopSelf();}}
 public void onDestroy(){if(view!=null){try{wm.removeView(view);}catch(IllegalArgumentException ignored){}view=null;}stopForeground(true);super.onDestroy();}
}
